//! Counting words.

use std::collections::BTreeMap;

/// How often each word occurs in `text`. A word is a maximal run of alphanumeric
/// characters.
pub fn counts(text: &str) -> BTreeMap<String, usize> {
    let mut out = BTreeMap::new();
    for w in text.split(|c: char| !c.is_alphanumeric()).filter(|w| !w.is_empty()) {
        *out.entry(w.to_string()).or_insert(0) += 1;
    }
    out
}

