//! Ranking words.

use crate::count::counts;

/// The `n` most frequent words of `text` with their counts, most frequent first.
pub fn top(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut all: Vec<(String, usize)> = counts(text).into_iter().collect();
    all.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| b.0.cmp(&a.0)));
    all.truncate(n);
    all
}

