use std::path::{Path, PathBuf};
use std::process::Command;

/// A fresh fixture directory for one test.
fn fixture(name: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!("smoke-{name}"));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("fixture dir");
    dir
}

fn write(dir: &Path, rel: &str, body: &str) {
    let p = dir.join(rel);
    std::fs::create_dir_all(p.parent().expect("parent")).expect("mkdir");
    std::fs::write(p, body).expect("write");
}

/// Run solve.sh with `dir` as the working directory.
fn solve(dir: &Path) -> bool {
    let script = Path::new(env!("CARGO_MANIFEST_DIR")).join("solve.sh");
    Command::new("sh")
        .arg(script)
        .current_dir(dir)
        .status()
        .expect("sh runs")
        .success()
}

#[test]
fn solve_script_is_present() {
    assert!(Path::new(env!("CARGO_MANIFEST_DIR")).join("solve.sh").is_file());
}

fn inbox(name: &str) -> PathBuf {
    let dir = fixture(name);
    write(&dir, "inbox/notes.txt", "n");
    write(&dir, "inbox/photo.png", "p");
    write(&dir, "inbox/table.csv", "a,b");
    write(&dir, "inbox/README", "r");
    dir
}

#[test]
fn files_move_by_extension() {
    let dir = inbox("by-ext");
    assert!(solve(&dir));
    assert!(dir.join("sorted/txt/notes.txt").is_file());
    assert!(dir.join("sorted/png/photo.png").is_file());
    let csv = std::fs::read_to_string(dir.join("sorted/csv/table.csv")).expect("csv");
    assert_eq!(csv, "a,b");
}

#[test]
fn extensionless_goes_to_other() {
    let dir = inbox("other");
    assert!(solve(&dir));
    assert!(dir.join("sorted/other/README").is_file());
}

#[test]
fn inbox_is_left_empty() {
    let dir = inbox("empty");
    assert!(solve(&dir));
    let left = std::fs::read_dir(dir.join("inbox")).expect("inbox").count();
